import os
from contextlib import contextmanager
from inspect import stack
from logging import Logger
from threading import Thread, Event

from taf.sbts.oam.coam.admin import admin as taf_admin
from taf.sbts.oam.coam.admin.exceptions import AliasInUse

from ta_logcollector.logger import get_net_logger
from ta_logcollector.settings import SERVER_HOST

IMS_ALIAS = "ims_{}".format(SERVER_HOST)
logger = Logger("LC")
ADMIN_SETUP_TIMEOUT = 30


def _setup_admin_in_background(admin, admin_ev):
    # type: (taf_admin, Event) -> None
    while not admin_ev.is_set():
        try:
            admin.setup_admin(timeout=ADMIN_SETUP_TIMEOUT, alias=IMS_ALIAS)
            logger.debug("Admin setup completed")
            admin_ev.set()
        except AliasInUse:
            admin_ev.set()
            logger.debug("Alias in use")
        except Exception as err:
            logger.debug(err, exc_info=True)


def start(admin_data):
    # type: (Dict[str, Any]) -> Thread
    """
    Method should start collecting ims log.
    :param admin_data: Data for admin - instance, event and thread
    :raise Exception: Calls stop() and re-raises previously caught exception
    """
    logger.info("inside {} before start".format(os.path.basename(__name__)))
    admin_th = admin_data["thread"]
    admin_th.start()
    logger.debug("Waiting for admin to connect to BTS")
    admin_th.join(ADMIN_SETUP_TIMEOUT + 2)
    if admin_th.is_alive() is True:
        logger.warning("Setup admin has failed. Retry will occur in background")
    logger.info("inside {} after start".format(os.path.basename(__name__)))
    return admin_th


def stop(admin_data, log_dir="/tmp/", file_name="infomodel_{}.ims2".format(SERVER_HOST)):
    # type: (Dict[str, Any], str, str) -> None
    """
    Method should stop collecting ims log and save it.
    :param admin_data: Data for admin - instance, event and thread
    :param log_dir: directory where syslog should be stored
    :param file_name: name of ims log file
    """
    logger.info("Inside {} before stop.".format(__name__))
    _stop_background_thread(admin_data["event"], admin_data["thread"])
    log_path = os.path.join(log_dir, file_name)
    admin_instance = admin_data["instance"]
    try:
        logger.debug("Collecting infomodel log")
        admin_instance.collect_infomodel_log_from_current_session(log_path, connection=IMS_ALIAS)
        logger.debug("Collected infomodel log")
    except Exception as err:
        logger.warning("Collecting infomodel log has failed : {}".format(err), exc_info=True)
        logger.debug("Infomodel failed", exc_info=True)
    finally:
        try:
            admin_instance.teardown_admin(connection=IMS_ALIAS)
        except Exception as err:
            logger.debug(err, exc_info=True)
    logger.info("inside {} after stop".format(__name__))


def _stop_background_thread(admin_ev, admin_th):
    # type: (Event, Thread) -> None
    admin_ev.set()
    admin_th.join()


def _prepare_admin_data():
    instance = taf_admin()
    event = Event()
    return {
        "instance": instance,
        "event": event,
        "thread": Thread(target=_setup_admin_in_background, args=(instance, event)),
    }


@contextmanager
def ims(log_host, log_port, file_name="infomodel_{}.ims2".format(SERVER_HOST), **kwargs):
    # type: (str, int, str, dict) -> Iterator[None]
    """
    Plugin for gathering ims log. It starts ims module and yields, waiting to be finished.

    :param log_host: IP address of logger host
    :param log_port: port of logger host
    :param file_name: name of ims log file
    """
    global logger
    logger = get_net_logger(log_host, log_port, "{}_{}".format(stack(0)[0][3], SERVER_HOST))
    log_dir = kwargs.pop("log_dir")
    admin_data = _prepare_admin_data()
    try:
        start(admin_data)
        yield
    finally:
        stop(admin_data, log_dir, file_name)
